<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { cast } from '../../data/playroom.js';
import { activityKinds } from '../../room/activityLog.js';
import { activityDestinations, companionDiaryLimit, diaryGroups } from '../../room/companionDiary.js';
import { readWorks, restoreWork, worksKey } from '../../room/workshelf.js';
import { useCompanion } from '../../composables/useCompanion.js';
import CompanionControls from '../CompanionControls.vue';
const { state, saved, pinMemory, linkMemory, deleteMemory } = useCompanion();
const person = computed(() => cast.find(c => c.id === state.value.member));
const asset = path => `${import.meta.env.BASE_URL}${path}`;
const router = useRouter(), favoritesOnly = ref(false), date = ref(''), deleting = ref(''), linking = ref(''), workChoice = ref(''), message = ref('');
const works = ref(readWorks());
const grouped = computed(() => diaryGroups(state.value.diary, { pinned: favoritesOnly.value, date: date.value }));
const pinnedCount = computed(() => state.value.diary.filter(memory => memory.pinned).length);
const memoryMember = memory => cast.find(member => member.id === memory.member)?.name || '一里';
const workFor = memory => works.value.find(work => work.id === memory.workId);
function refreshWorks(event) { if (!event || event.type !== 'storage' || event.key === worksKey || event.key === null) works.value = readWorks(); }
function pin(memory) { pinMemory(memory.id, !memory.pinned); message.value = memory.pinned ? '已取消重要回忆。' : '这一页已夹进重要回忆。'; }
function chooseWork(memory) { linking.value = memory.id; workChoice.value = memory.workId; }
function saveLink(memory) {
  const work = works.value.find(work => work.id === workChoice.value);
  linkMemory(memory.id, work); linking.value = ''; message.value = work ? `已关联作品「${work.title}」。` : '已移除作品关联，回忆仍保留。';
}
function remove(memory) { deleteMemory(memory.id); deleting.value = ''; message.value = '这一页已删除，不会从近期活动中自动重新出现。'; }
async function openWork(memory) {
  try { const target = restoreWork(memory.workId); await router.push(target); }
  catch (error) { message.value = error.message; refreshWorks(); }
}
onMounted(() => { window.addEventListener('hitori:works-changed', refreshWorks); window.addEventListener('storage', refreshWorks); window.addEventListener('hitori:sync-applied', refreshWorks); });
onBeforeUnmount(() => { window.removeEventListener('hitori:works-changed', refreshWorks); window.removeEventListener('storage', refreshWorks); window.removeEventListener('hitori:sync-applied', refreshWorks); });
</script>
<template>
  <section class="room-panel" aria-labelledby="companion-title"><div class="play-heading"><div><p class="play-eyebrow">SOMEONE TO REMEMBER / 有人记得今天</p><h2 id="companion-title">那些小事，她都认真收好了。</h2><p class="room-intro">打个招呼，送一件纪念物。完成小屋活动后，伙伴会回应，也会留下一页新的记忆。</p></div><span class="play-number" aria-hidden="true">09</span></div><div class="companion-desk"><div class="companion-portrait" :style="{ '--buddy-color': person.color }"><span aria-hidden="true">ひとりじゃない。</span><img :src="asset(person.image)" :alt="person.name" width="260" height="300"><strong>{{ person.name }}</strong><p>从一件小事，到下一件小事。<br>今天也有人，和你待在一起。</p></div><CompanionControls /></div>
    <section class="companion-diary" aria-labelledby="diary-title"><p class="play-eyebrow">AFTER SCHOOL DIARY / 放学后长期手帐</p><h3 id="diary-title">把日子，一页页翻回来。</h3><p class="room-hint">每页保留当时陪伴你的成员与原创回应，可以夹星、关联一件作品，再回到那次活动。当前 {{ state.diary.length }} / {{ companionDiaryLimit }} 页，重要回忆 {{ pinnedCount }} 页。</p><div class="diary-filters"><label class="room-check"><input v-model="favoritesOnly" type="checkbox">只看重要回忆</label><label class="room-field">回看日期<input v-model="date" type="date" aria-label="手帐日期"></label><button v-if="date || favoritesOnly" type="button" @click="date = ''; favoritesOnly = false">看全部日期</button></div>
      <p class="room-status" role="status">{{ message }}</p><div v-if="grouped.length" class="diary-days"><section v-for="day in grouped" :key="day.date" class="diary-day"><h4><time>{{ day.date }}</time><span>{{ day.memories.length }} 页</span></h4><ol><li v-for="memory in day.memories" :key="memory.id" class="diary-page" :class="{ pinned: memory.pinned }"><div class="diary-page-heading"><span>{{ activityKinds[memory.kind] }} · {{ memoryMember(memory) }}陪你记下</span><button type="button" :aria-pressed="memory.pinned" :aria-label="`${memory.pinned ? '取消重要回忆' : '收藏重要回忆'}：${memory.detail}`" @click="pin(memory)">{{ memory.pinned ? '★ 已夹星' : '☆ 夹星' }}</button></div><strong>{{ memory.detail }}</strong><p class="diary-reply">{{ memory.reply || '这件小事，也值得被认真记住。' }}</p><div v-if="memory.workId" class="diary-work"><p v-if="workFor(memory)">关联作品：{{ workFor(memory).title }}</p><p v-else>曾关联「{{ memory.workTitle || '这份作品' }}」。作品已移走或不在本机，回忆仍留在这里。</p><button v-if="workFor(memory)" type="button" @click="openWork(memory)">继续编辑关联作品</button></div><div class="diary-actions"><RouterLink :to="`/room/${activityDestinations[memory.kind]}`">再去{{ activityKinds[memory.kind] }} ↗</RouterLink><button type="button" @click="chooseWork(memory)">{{ memory.workId ? '调整作品关联' : '关联一件作品' }}</button><button type="button" @click="deleting = memory.id">删除这一页</button></div><div v-if="linking === memory.id" class="diary-inline"><label class="room-field">选择本机作品<select v-model="workChoice"><option value="">不关联作品</option><option v-for="work in works" :key="work.id" :value="work.id">{{ work.title }}</option></select></label><p v-if="!works.length" class="room-hint">作品架还空着。在创作页点「存入作品架」后，就能把那件作品夹到手帐里。</p><div class="room-actions"><button type="button" @click="saveLink(memory)">保存关联</button><button type="button" @click="linking = ''">取消</button></div></div><div v-if="deleting === memory.id" class="diary-inline" role="group" aria-label="确认删除回忆"><p>删除这一页回忆？关联的作品和活动记录会继续保留。</p><div class="room-actions"><button type="button" @click="remove(memory)">确认删除这一页</button><button type="button" @click="deleting = ''">留下这一页</button></div></div></li></ol></section></div><p v-else class="diary-empty">{{ favoritesOnly || date ? '这里暂时没有这一类回忆。试试其他日期，或给喜欢的一页夹颗星。' : '手帐的第一页，还等着今天的小事。去完成一次练习、保存一段编曲，或导出一张合影，再回来翻翻吧。' }}</p>
      <p class="room-hint">{{ saved ? '手帐保存在当前设备。' : '浏览器暂时无法保存，手帐本次仍可查看。' }} 回应由本站原创，不是官方台词。最多保留 {{ companionDiaryLimit }} 页，先保留已夹星的旧页，再整理其余旧页；删页不会删除作品，也不会增加作品架容量。</p>
    </section>
  </section>
</template>
<style scoped>
