ed #c0a3b5;font-size:13px}.diary-empty{padding:24px;background:#f1e6ea;font-size:13px;line-height:1.9}@media(max-width:760px){.companion-desk{grid-template-columns:1fr;gap:20px}.companion-portrait{position:static;padding:22px}.companion-portrait img{height:180px;margin:15px auto}.diary-page{padding:14px}.diary-page-heading{align-items:flex-start;flex-direction:column}.diary-filters{gap:10px}.companion-diary{margin-top:24px}}
